.proj-box { border-top: 1px solid var(--border-strong); padding: 8px 12px 10px; background: #fbfcfe; }
.proj-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 1px 10px; margin-top: 6px; }
.proj-grid label {
  display: flex; align-items: center; gap: 5px;
  font-size: 11.5px; color: var(--slate); cursor: pointer;
  padding: 2px 2px; white-space: nowrap;
}
.proj-grid label:hover { color: var(--text); }
.proj-grid input { accent-color: var(--violet); margin: 0; }
.proj-foot { margin-top: 6px; font-size: 10.5px; color: var(--faint); display: flex; justify-content: space-between; }
.proj-foot button { border: none; background: none; color: var(--violet); font-size: 10.5px; padding: 0; }
.proj-foot button:hover { text-decoration: underline; }

/* data region (center, dominant) */
.data-region { flex: 1; min-width: 0; background: var(--panel); display: flex; flex-direction: column; }
.grid-scroll { overflow: auto; flex: 1; }
table.grid { border-collapse: separate; border-spacing: 0; width: 100%; font-size: 12px; }
table.grid th, table.grid td {
  border-bottom: 1px solid var(--border);
  padding: 4px 10px; text-align: left; white-space: nowrap;
  max-width: 220px; overflow: hidden; text-overflow: ellipsis;
}
table.grid thead th {
  position: sticky; top: 0; z-index: 2;
  background: #f8fafc; color: var(--muted);
  font-size: 11px; font-weight: 600;
  border-bottom: 1px solid var(--border-strong);
  cursor: pointer; user-select: none;
}
table.grid thead th:hover { background: #eef2f7; }
table.grid thead th.sorted { color: var(--accent); }
table.grid thead th .dir { font-size: 9px; margin-left: 2px; }
table.grid thead th:first-child, table.grid td:first-child { position: sticky; left: 0; background: var(--panel); z-index: 1; }
table.grid thead th:first-child { z-index: 3; background: #f8fafc; }
table.grid td.num, table.grid th.num { text-align: right; font-variant-numeric: tabular-nums; color: var(--slate); }
table.grid tbody tr { cursor: pointer; }
table.grid tbody tr:hover td { background: #f5f8fc; }
table.grid tbody tr.selected td { background: var(--accent-soft); }
table.grid tbody tr.selected td:first-child { box-shadow: inset 2px 0 0 var(--accent); }
table.grid td.dim-cell { color: var(--slate); }
.pri { font-weight: 600; }
.pri-P0 { color: var(--danger); } .pri-P1 { color: var(--orange); }
.st-在线 { color: var(--green); } .st-已下线 { color: var(--faint); text-decoration: line-through; }
.st-开发中 { color: var(--accent); } .st-公测 { color: var(--violet); }
.health-good { color: var(--green); } .health-mid { color: var(--orange); } .health-bad { color: var(--danger); }

.empty-state {
  margin: auto; text-align: center; color: var(--muted); padding: 60px 20px;
}
.empty-state .big { font-size: 15px; margin-bottom: 8px; }
.empty-state button {
  margin-top: 12px; background: var(--accent); color: #fff;
  border: none; border-radius: var(--radius); padding: 6px 16px; font-size: 12.5px;
}
.empty-state button:hover { background: #1d4fd8; }

.error-state { margin: auto; text-align: center; color: var(--danger); padding: 60px 20px; }

/* right panel */
.right-panel {
  width: 316px; flex: none; background: var(--panel);
  border-left: 1px solid var(--border);
  display: flex; flex-direction: column; min-height: 0;
}
.inspector { flex: none; max-height: 46%; display: flex; flex-direction: column; border-bottom: 1px solid var(--border-strong); }
.inspector .panel-title { padding: 10px 14px 6px; }
.insp-body { overflow-y: auto; padding: 0 14px 12px; }
.insp-name { font-size: 13.5px; font-weight: 600; margin-bottom: 2px; }
.insp-warn {
  margin: 6px 0; font-size: 11px; color: var(--orange);
  background: var(--orange-soft); border-radius: var(--radius); padding: 5px 8px;
}
.insp-dl { display: grid; grid-template-columns: 66px 1fr; gap: 3px 8px; margin-top: 8px; }
.insp-dl dt { color: var(--faint); font-size: 11.5px; }
.insp-dl dd { font-size: 12px; color: var(--text); font-variant-numeric: tabular-nums; }
.insp-placeholder { color: var(--faint); font-size: 12px; padding: 14px 0 20px; line-height: 1.6; }

.trail { flex: 1; min-height: 0; display: flex; flex-direction: column; }
.trail .panel-title { padding: 10px 14px 4px; }
.trail-pos { margin-left: auto; font-weight: 500; color: var(--faint); font-variant-numeric: tabular-nums; text-transform: none; letter-spacing: 0; }
.trail-hint { font-size: 10.5px; color: var(--faint); padding: 0 14px 6px; }
#trail { list-style: none; overflow-y: auto; flex: 1; padding: 0 8px 10px; }
#trail li {
  display: flex; gap: 7px; align-items: baseline;
  padding: 4px 8px; border-radius: var(--radius);
  cursor: pointer; font-size: 11.5px; color: var(--slate);
  border-left: 2px solid transparent;
}
#trail li:hover { background: var(--bg); }
#trail li .seq { color: var(--faint); font-variant-numeric: tabular-nums; flex: none; width: 30px; }
#trail li .lbl { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
#trail li .ts { color: var(--faint); font-size: 10px; font-variant-numeric: tabular-nums; flex: none; }
#trail li.current { background: var(--accent-soft); border-left-color: var(--accent); color: var(--text); font-weight: 600; }
#trail li.future { opacity: .45; }
#trail li.future .lbl::after { content: " ⤴回退点"; font-size: 10px; color: var(--orange); }

/* footer acceptance strip */
.acceptance {
  flex: none; background: var(--panel); border-top: 1px solid var(--border);
  padding: 3px 12px; font-size: 10.5px; color: var(--faint);
  display: flex; gap: 14px; align-items: center;
}
.acceptance .k { color: var(--green); }
kbd {
  font-family: Consolas, monospace; font-size: 10px;
  background: var(--slate-soft); border: 1px solid var(--border-strong);
  border-bottom-width: 2px; border-radius: 3px; padding: 0 4px; color: var(--slate);
}

