1	/* 维界 Lens — cell-j13-s10 · explore × dimensional-space
2	 * 单屏多维数据集探索器 · PAT-DATA-EXPLORER + Contextual Inspector
3	 *
4	 * SDIR 契约（screen: data_explorer_screen）
5	 *  regions   : data(dominant/collection) · dimension-panel · lens-bar · inspector(selection_driven)
6	 *              · trail · overview(contextual)
7	 *  states    : ready(首屏即此态，数据内联) / selected / empty(零匹配) / error(完整性校验失败)
8	 *              loading 定义但按设计不可达 —— 初始数据随首屏就绪，不存在可测加载态
9	 *  ownership : lens（过滤+投影+排序+观察轴+搜索）单一状态所有者，作用于 DATASET；
10	 *              selection 归 data 区域，跨维度切换/撤销持久保留（维度切换不重置认知）
11	 *  revert    : revisions 时间旅行 —— 逐条 undo/redo（Ctrl+Z / Ctrl+Shift+Z / Ctrl+Y）、
12	 *              轨迹点击任意步回退、chip 逐条移除、reset 一键回初始（本身可撤销）
13	 *  keyboard  : 2 个契约（undo/redo 组合键；Esc 取消选中）
14	 *  budget    : permanent_panels=4 · primary_actions=3 · modes=0 · state_owners=1 ·
15	 *              navigation_levels=1 · new_semantic_concepts=2(透镜/变更轨迹) · surfaces=1
16	 *  acceptance: 维度切换不重置认知 · 过滤/投影状态有归属且可回退 · 首屏 ready
17	 */
18	(function () {
19	  'use strict';
20	
21	  const DS = window.DATASET;
22	  const app = document.getElementById('app');
23	  const dimByKey = {};
24	  DS.dims.forEach((d) => { dimByKey[d.key] = d; });
25	
26	  const DEFAULT_PROJECTION = { category: 1, platform: 1, status: 1, priority: 1, mrr: 1, health: 1 };
27	
28	  const clone = (o) => JSON.parse(JSON.stringify(o));
29	  const pad2 = (n) => String(n).padStart(2, '0');
30	  const nowTs = () => { const d = new Date(); return pad2(d.getHours()) + ':' + pad2(d.getMinutes()) + ':' + pad2(d.getSeconds()); };
31	  const esc = (s) => String(s).replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
32	
33	  /* ---------------- lens store（单一状态所有者 + revision 时间旅行） ---------------- */
34	  const INITIAL_LENS = { focus: 'category', filters: {}, projection: clone(DEFAULT_PROJECTION), sort: null, search: '' };
35	
36	  const state = {
37	    lens: clone(INITIAL_LENS),
38	    revisions: [{ seq: 0, op: 'init', label: '初始视角', target: '—', ts: nowTs(), lens: clone(INITIAL_LENS) }],
39	    pointer: 0,
40	    selectedId: null,
41	    phase: 'ready' // ready | selected | empty | error（loading 按设计不可达：数据内联）
42	  };
43	
44	  const opLabel = { init: '初始', filter: '过滤', unfilter: '取消过滤', 'clear-filters': '清除过滤', focus: '观察轴', 'project-add': '投影+', 'project-remove': '投影−', 'project-reset': '默认投影', sort: '排序', 'clear-sort': '清除排序', search: '搜索', 'clear-search': '清除搜索', reset: '重置' };
45	
46	  function commit(op, label, target, mutator) {
47	    const next = mutator(clone(state.lens));
48	    state.revisions = state.revisions.slice(0, state.pointer + 1);
49	    state.revisions.push({ seq: state.revisions[state.pointer].seq + 1, op, label, target, ts: nowTs(), lens: next });
50	    state.pointer = state.revisions.length - 1;
51	    state.lens = next;
52	    update(); // 单一出口：任何透镜变更后全量刷新
53	  }
54	  const sameLens = (a, b) => JSON.stringify(a) === JSON.stringify(b);
55	
56	  const actions = {
57	    setFocus(dim) {
58	      if (dim === state.lens.focus) return;
59	      commit('focus', '观察轴 → ' + dimByKey[dim].label, dim, (l) => { l.focus = dim; return l; });
60	    },
61	    toggleFilter(dim, val) {
62	      const on = (state.lens.filters[dim] || []).indexOf(val) >= 0;
63	      commit(on ? 'unfilter' : 'filter', (on ? '取消过滤 ' : '过滤 ') + dimByKey[dim].label + '=' + val, dim + '=' + val, (l) => {
64	        const arr = (l.filters[dim] || []).filter((v) => v !== val);
65	        if (arr.length) l.filters[dim] = arr; else delete l.filters[dim];
66	        if (!on) { (l.filters[dim] = l.filters[dim] || []).push(val); }
67	        return l;
68	      });
69	    },
70	    clearFilters() {
71	      if (!Object.keys(state.lens.filters).length) return;
72	      commit('clear-filters', '清除全部过滤（' + Object.keys(state.lens.filters).length + ' 个维度）', 'filters', (l) => { l.filters = {}; return l; });
73	    },
74	    toggleProjection(key) {
75	      const label = dimByKey[key] ? dimByKey[key].label : (DS.metrics.find((m) => m.key === key) || {}).label;
76	      const on = !!state.lens.projection[key];
77	      const restCount = Object.keys(state.lens.projection).filter((k) => state.lens.projection[k]).length;
78	      if (on && restCount <= 1) return; // 至少保留一列
79	      commit(on ? 'project-remove' : 'project-add', (on ? '移除投影列 · ' : '添加投影列 · ') + label, key, (l) => {
80	        if (on) delete l.projection[key]; else l.projection[key] = 1;
81	        return l;
82	      });
83	    },
84	    resetProjection() {
85	      if (sameLens(state.lens.projection, DEFAULT_PROJECTION)) return;
86	      commit('project-reset', '恢复默认投影（6 列）', 'projection', (l) => { l.projection = clone(DEFAULT_PROJECTION); return l; });
87	    },
88	    setSort(key) {
89	      const cur = state.lens.sort;
90	      const dir = !cur || cur.key !== key ? 'asc' : cur.dir === 'asc' ? 'desc' : null;
91	      if (!dir) {
92	        commit('clear-sort', '清除排序', key, (l) => { l.sort = null; return l; });
93	      } else {
94	        const label = key === 'name' ? '条目' : (dimByKey[key] || DS.metrics.find((m) => m.key === key)).label;
95	        commit('sort', '排序 · ' + label + (dir === 'asc' ? ' ↑' : ' ↓'), key, (l) => { l.sort = { key, dir }; return l; });
96	      }
97	    },
98	    setSearch(text) {
99	      const cur = state.lens.search || '';
100	      if (text === cur) return;
101	      commit(text ? 'search' : 'clear-search', text ? '搜索 · "' + text + '"' : '清除搜索', 'search', (l) => { l.search = text; return l; });
102	    },
103	    resetLens() {
104	      if (sameLens(state.lens, INITIAL_LENS)) return;
105	      commit('reset', '重置到初始视角', 'lens', () => clone(INITIAL_LENS));
106	    },
107	    undo() { if (state.pointer > 0) { state.pointer--; state.lens = state.revisions[state.pointer].lens; } },
108	    redo() { if (state.pointer < state.revisions.length - 1) { state.pointer++; state.lens = state.revisions[state.pointer].lens; } },
109	    jump(i) { if (i >= 0 && i < state.revisions.length) { state.pointer = i; state.lens = state.revisions[i].lens; } },
110	    select(id) { state.selectedId = state.selectedId === id ? null : id; update(); }
111	  };
112	
113	  /* ---------------- 派生：匹配集 / 分面计数 ---------------- */
114	  function passesFilters(r, filters, skipDim) {
115	    for (const k in filters) {
116	      if (k === skipDim) continue;
117	      if (filters[k].indexOf(r[k]) < 0) return false;
118	    }
119	    return true;
120	  }
121	  function matched() {
122	    const { filters, search } = state.lens;
123	    const q = (search || '').trim().toLowerCase();
124	    let rows = DS.records.filter((r) => passesFilters(r, filters, null));
125	    if (q) rows = rows.filter((r) => (r.name + ' ' + DS.dims.map((d) => r[d.key]).join(' ')).toLowerCase().indexOf(q) >= 0);
126	    return rows;
127	  }
128	  function sorted(rows) {
129	    const s = state.lens.sort;
130	    if (!s) return rows;
131	    const isNum = !!DS.metrics.find((m) => m.key === s.key);
132	    const dir = s.dir === 'asc' ? 1 : -1;
133	    return rows.slice().sort((a, b) => {
134	      if (isNum) return (a[s.key] - b[s.key]) * dir;
135	      return String(a[s.key]).localeCompare(String(b[s.key]), 'zh') * dir;
136	    });
137	  }
138	  function facetCounts() {
139	    const dim = dimByKey[state.lens.focus];
140	    const base = DS.records.filter((r) => passesFilters(r, state.lens.filters, dim.key));
141	    const counts = {};
142	    dim.values.forEach((v) => { counts[v] = 0; });
143	    base.forEach((r) => { counts[r[dim.key]]++; });
144	    return { dim, counts, base: base.length };
145	  }
146	
147	  /* ---------------- DOM 骨架（构建一次；动态区按需重渲染） ---------------- */
148	  function buildSkeleton() {
149	    app.innerHTML =
150	      '<header class="lensbar" data-region="lens-bar">' +
151	      '  <div class="lens-top">' +
152	      '    <div class="brand"><span class="logo">◈ 维界 Lens</span><span class="ds-name">' + esc(DS.name) + ' <em style="font-style:normal;color:#b3bccb">· ' + esc(DS.note) + '</em></span></div>' +
153	      '    <span class="ownership" title="过滤/投影状态归属：透镜明确作用于该数据集">作用于 · ' + esc(DS.name) + '</span>' +
154	      '    <div class="overview" id="overview" data-region="overview"></div>' +
155	      '    <div class="hist-controls">' +
156	      '      <button id="btn-undo" title="撤销 (Ctrl+Z)">↶ 撤销</button>' +
157	      '      <button id="btn-redo" title="重做 (Ctrl+Shift+Z / Ctrl+Y)">↷ 重做</button>' +
158	      '      <button id="btn-reset" title="重置到初始视角（本身可撤销）">⭯ 重置</button>' +
159	      '    </div>' +
160	      '  </div>' +
161	      '  <div class="lens-chips">' +
162	      '    <span class="search-box"><span class="icon">⌕</span><input id="search-input" type="text" placeholder="跨维度搜索…（按 / 聚焦）" /></span>' +
163	      '    <span class="group-label">生效视角</span>' +
164	      '    <span id="chips" style="display:contents"></span>' +
165	      '    <span class="match-count" id="match-count"></span>' +
166	      '  </div>' +
167	      '</header>' +
168	      '<div class="workspace">' +
169	      '  <aside class="dim-panel" data-region="dimension-panel">' +
170	      '    <div class="panel-title">维度 <span class="n">' + DS.dims.length + '</span></div>' +
171	      '    <div class="hint">点击维度切换<b>观察轴</b>（不重置选择/过滤）· 点值切换过滤</div>' +
172	      '    <div class="dim-scroll"><ul id="dim-list"></ul></div>' +
173	      '    <div class="proj-box" id="proj-box">' +
174	      '      <div class="panel-title">投影列 <span class="n" id="proj-count"></span></div>' +
175	      '      <div class="proj-grid" id="proj-grid"></div>' +
176	      '      <div class="proj-foot"><span>列变更记入变更轨迹</span><button id="btn-proj-reset">恢复默认</button></div>' +
177	      '    </div>' +
178	      '  </aside>' +
179	      '  <section class="data-region" data-region="data"><div class="grid-scroll" id="grid-scroll"></div></section>' +
180	      '  <aside class="right-panel">' +
181	      '    <div class="inspector" data-region="inspector">' +
182	      '      <div class="panel-title">条目详情 <span class="n" id="insp-state"></span></div>' +
183	      '      <div class="insp-body" id="insp-body"></div>' +
184	      '    </div>' +
185	      '    <div class="trail" data-region="trail">' +
186	      '      <div class="panel-title">变更轨迹 <span class="trail-pos" id="trail-pos"></span></div>' +
187	      '      <div class="trail-hint">每步含操作·目标·时间 · 点击任意步回退（后续操作将分叉）</div>' +
188	      '      <ol id="trail"></ol>' +
189	      '    </div>' +
190	      '  </aside>' +
191	      '</div>' +
192	      '<footer class="acceptance">' +
193	      '  <span><b class="k">✓</b> 维度切换不重置认知</span>' +
194	      '  <span><b class="k">✓</b> 过滤/投影状态有归属且可回退</span>' +
195	      '  <span><b class="k">✓</b> 首屏即 ready（数据内联）</span>' +
196	      '  <span style="margin-left:auto"><kbd>Ctrl+Z</kbd> 撤销 · <kbd>Ctrl+Shift+Z</kbd> 重做 · <kbd>Esc</kbd> 取消选中 · <kbd>/</kbd> 搜索</span>' +
197	      '</footer>';
198	  }
199	
200	  /* ---------------- 各区域渲染 ---------------- */
201	  function findIntro(op, target) {
202	    for (let i = state.pointer; i >= 0; i--) {
203	      const r = state.revisions[i];
204	      if (r.op === op && r.target === target) return r;
205	    }
206	    return null;
207	  }
208	
209	  function renderChips() {
210	    const l = state.lens;
211	    const chips = [];
212	    const defaultFocus = l.focus === INITIAL_LENS.focus;
213	    const intro = findIntro('focus', l.focus);
214	    chips.push('<span class="chip chip-focus" title="观察轴（维度切换）' + (intro ? ' · 来自 #' + intro.seq + ' ' + (opLabel[intro.op] || intro.op) + ' ' + intro.ts : ' · 初始') + '">观察轴 · ' + esc(dimByKey[l.focus].label) +
215	      (defaultFocus ? '' : '<button class="x" data-x="focus" title="恢复观察轴为 ' + esc(dimByKey[INITIAL_LENS.focus].label) + '（记入轨迹）">×</button>') + '</span>');
216	    let filterCount = 0;
217	    DS.dims.forEach((d) => {
218	      (l.filters[d.key] || []).forEach((v) => {
219	        filterCount++;
220	        const src = findIntro('filter', d.key + '=' + v);
221	        chips.push('<span class="chip chip-filter" title="过滤条件 · 作用维度：' + esc(d.label) + (src ? ' · 来自 #' + src.seq + ' ' + src.ts : '') + '"><span class="src">过滤</span>' + esc(d.label) + ' = ' + esc(v) + '<button class="x" data-x="filter" data-dim="' + d.key + '" data-val="' + esc(v) + '" title="移除此过滤（记入轨迹，可撤销）">×</button></span>');
222	      });
223	    });
224	    if (filterCount >= 2) chips.push('<span class="chip chip-filter" style="opacity:.75"><button class="x" data-x="clear-filters" style="width:auto;background:none;padding:0 2px 0 0" title="清除全部过滤（记入轨迹，可撤销）">清空过滤 ×</button></span>');
225	    if (!sameLens(l.projection, DEFAULT_PROJECTION)) {
226	      const n = Object.keys(l.projection).filter((k) => l.projection[k]).length;
227	      const total = DS.dims.length + DS.metrics.length;
228	      chips.push('<span class="chip chip-project" title="投影状态 · 当前 ' + n + '/' + total + ' 列 · 与默认投影不同 · 点击 × 恢复默认（记入轨迹）"><span class="src">投影</span>' + n + '/' + total + ' 列<button class="x" data-x="project-reset" title="恢复默认投影（记入轨迹）">×</button></span>');
229	    }
230	    if (l.sort) {
231	      const label = l.sort.key === 'name' ? '条目' : (dimByKey[l.sort.key] || DS.metrics.find((m) => m.key === l.sort.key)).label;
232	      chips.push('<span class="chip chip-sort" title="排序状态 · 作用列：' + esc(label) + '"><span class="src">排序</span>' + esc(label) + ' ' + (l.sort.dir === 'asc' ? '↑' : '↓') + '<button class="x" data-x="clear-sort" title="清除排序（记入轨迹）">×</button></span>');
233	    }
234	    if (l.search) chips.push('<span class="chip chip-search" title="搜索状态 · 作用于名称与全部维度值"><span class="src">搜索</span>"' + esc(l.search) + '"<button class="x" data-x="clear-search" title="清除搜索（记入轨迹）">×</button></span>');
235	    if (!chips.length) chips.push('<span class="chip chip-empty">初始视角 · 无过滤</span>');
236	    document.getElementById('chips').innerHTML = chips.join('');
237	  }
238	
239	  function renderHeader(matchedCount) {
240	    document.getElementById('overview').innerHTML =
241	      '<b>' + DS.total + '</b> 条 · 匹配 <b>' + matchedCount + '</b> · ' + DS.dims.length + ' 维度 · 轨迹 ' + (state.pointer + 1) + '/' + state.revisions.length;
242	    document.getElementById('match-count').innerHTML = '匹配 <b>' + matchedCount + '</b> / ' + DS.total;
243	    document.getElementById('btn-undo').disabled = state.pointer <= 0;
244	    document.getElementById('btn-redo').disabled = state.pointer >= state.revisions.length - 1;
245	    document.getElementById('btn-reset').disabled = sameLens(state.lens, INITIAL_LENS);
246	    const si = document.getElementById('search-input');
247	    if (si.value !== (state.lens.search || '')) si.value = state.lens.search || '';
248	  }
249	
250	  function renderDimPanel() {
251	    const { dim, counts } = facetCounts();
252	    const max = Math.max(1, ...Object.values(counts));
253	    const active = state.lens.filters[dim.key] || [];
254	    let html = '';
255	    DS.dims.forEach((d) => {
256	      const n = (state.lens.filters[d.key] || []).length;
257	      if (d.key === dim.key) {
258	        html += '<li class="dim-item focused" data-dim="' + d.key + '"><div class="dim-head" title="当前观察轴 · 点击其他维度切换（不重置选择/过滤）"><span class="chev">▾</span>' + esc(d.label) + (n ? '<span class="badge">' + n + '</span>' : '') + '</div><div class="values">';
259	        d.values.forEach((v) => {
260	          const on = active.indexOf(v) >= 0;
261	          const w = Math.round(counts[v] / max * 100);
262	          html += '<div class="val' + (on ? ' active' : '') + '" data-dim="' + d.key + '" data-val="' + esc(v) + '" title="' + (on ? '取消' : '添加') + '过滤 ' + esc(d.label) + '=' + esc(v) + '（记入轨迹）">' +
263	            '<span class="vname">' + esc(v) + '</span><span class="bar"><i style="width:' + w + '%"></i></span><span class="vcount">' + counts[v] + '</span></div>';
264	        });
265	        html += '</div></li>';
266	      } else {
267	        html += '<li class="dim-item" data-dim="' + d.key + '"><div class="dim-head" title="切换观察轴到 ' + esc(d.label) + '（不重置选择/过滤，记入轨迹）"><span class="chev">▸</span>' + esc(d.label) + (n ? '<span class="badge">' + n + '</span>' : '') + '</div></li>';
268	      }
269	    });
270	    document.getElementById('dim-list').innerHTML = html;
271	
272	    // 投影列
273	    const pg = document.getElementById('proj-grid');
274	    let pj = '';
275	    DS.dims.forEach((d) => {
276	      const on = !!state.lens.projection[d.key];
277	      pj += '<label title="' + (on ? '移除' : '添加') + '投影列 ' + esc(d.label) + '（记入轨迹）"><input type="checkbox" data-proj="' + d.key + '"' + (on ? ' checked' : '') + '/>' + esc(d.label) + '</label>';
278	    });
279	    DS.metrics.forEach((m) => {
280	      const on = !!state.lens.projection[m.key];
281	      pj += '<label title="' + (on ? '移除' : '添加') + '投影列 ' + esc(m.label) + '（记入轨迹）"><input type="checkbox" data-proj="' + m.key + '"' + (on ? ' checked' : '') + '/>' + esc(m.label) + '</label>';
282	    });
283	    pg.innerHTML = pj;
284	    const n = Object.keys(state.lens.projection).filter((k) => state.lens.projection[k]).length;
285	    document.getElementById('proj-count').textContent = n + '/' + (DS.dims.length + DS.metrics.length);
286	  }
287	
288	  function cellHtml(r, key) {
289	    if (key === 'name') return '<td class="dim-cell" style="font-weight:600">' + esc(r.name) + '</td>';
290	    const m = DS.metrics.find((x) => x.key === key);
291	    if (m) {
292	      if (key === 'health') {
293	        const cls = r.health >= 68 ? 'good' : r.health >= 40 ? 'mid' : 'bad';
294	        return '<td class="num"><span class="health-' + cls + '">' + r.health + '</span></td>';
295	      }
296	      const v = r[key];
297	      const txt = key === 'mrr' ? (v >= 100 ? '¥' + Math.round(v) + '万' : '¥' + v.toFixed(1) + '万') : (v >= 100 ? Math.round(v) + '万' : v.toFixed(1) + '万');
298	      return '<td class="num">' + txt + '</td>';
299	    }
300	    let extra = '';
301	    if (key === 'priority') extra = ' class="dim-cell pri pri-' + esc(r.priority) + '"';
302	    else if (key === 'status') extra = ' class="dim-cell st-' + esc(r.status) + '"';
303	    return '<td' + extra + '>' + esc(r[key]) + '</td>';
304	  }
305	
306	  function renderGrid(rows) {
307	    const wrap = document.getElementById('grid-scroll');
308	    const l = state.lens;
309	    if (!rows.length) {
310	      const fcount = Object.keys(l.filters).reduce((a, k) => a + l.filters[k].length, 0);
311	      wrap.innerHTML = '<div class="empty-state" data-state="empty"><div class="big">没有匹配当前视角的数据条目</div>' +
312	        '<div>' + (fcount ? fcount + ' 个过滤值' : '') + (l.search ? (fcount ? ' · ' : '') + '搜索 "' + esc(l.search) + '"' : '') + ' · 调整或清除后即可恢复</div>' +
313	        (fcount ? '<button id="btn-empty-clear">清除全部过滤（记入轨迹，可撤销）</button>' : '') + '</div>';
314	      return;
315	    }
316	    state.phase = 'ready';
317	    let cols = [{ key: 'name', label: '条目' }];
318	    DS.dims.forEach((d) => { if (l.projection[d.key]) cols.push(d); });
319	    DS.metrics.forEach((m) => { if (l.projection[m.key]) cols.push(m); });
320	    let html = '<table class="grid"><thead><tr>' + cols.map((c) => {
321	      const sortedCls = l.sort && l.sort.key === c.key ? ' sorted' : '';
322	      const dir = l.sort && l.sort.key === c.key ? '<span class="dir">' + (l.sort.dir === 'asc' ? '▲' : '▼') + '</span>' : '';
323	      const numCls = c.num ? ' num' : '';
324	      return '<th class="th-sort' + numCls + sortedCls + '" data-sort="' + c.key + '" title="点击循环排序：升 → 降 → 无（记入轨迹）">' + esc(c.label) + dir + '</th>';
325	    }).join('') + '</tr></thead><tbody>';
326	    rows.forEach((r) => {
327	      html += '<tr data-id="' + r.id + '"' + (state.selectedId === r.id ? ' class="selected"' : '') + '>' + cols.map((c) => cellHtml(r, c.key)).join('') + '</tr>';
328	    });
329	    wrap.innerHTML = html + '</tbody></table>';
330	    state.phase = 'ready';
331	  }
332	
333	  function renderInspector() {
334	    const body = document.getElementById('insp-body');
335	    const badge = document.getElementById('insp-state');
336	    if (!state.selectedId) {
337	      badge.textContent = '';
338	      body.innerHTML = '<div class="insp-placeholder">在左侧数据表中点击一行查看该条目的<b>全维度详情</b>。<br/>选中状态跨维度切换 / 过滤调整保持不变。</div>';
339	      return;
340	    }
341	    const r = DS.records.find((x) => x.id === state.selectedId);
342	    const rows = matched();
343	    const excluded = !rows.some((x) => x.id === r.id);
344	    badge.textContent = '选中';
345	    body.innerHTML = '<div class="insp-name">' + esc(r.name) + '</div>' +
346	      (excluded ? '<div class="insp-warn" title="selection 归属 data 区域，不随透镜重置">⚠ 选中条目被当前视角排除 — 选择已保留，调整过滤即可找回</div>' : '') +
347	      '<dl class="insp-dl">' +
348	      DS.dims.map((d) => '<dt>' + esc(d.label) + '</dt><dd>' + esc(r[d.key]) + '</dd>').join('') +
349	      '<dt>MRR</dt><dd>¥' + r.mrr.toFixed(1) + ' 万</dd>' +
350	      '<dt>DAU</dt><dd>' + r.dau.toFixed(1) + ' 万</dd>' +
351	      '<dt>健康分</dt><dd>' + r.health + ' / 100</dd>' +
352	      '</dl>';
353	  }
354	
355	  function renderTrail() {
356	    document.getElementById('trail-pos').textContent = (state.pointer + 1) + '/' + state.revisions.length;
357	    document.getElementById('trail').innerHTML = state.revisions.map((r, i) => {
358	      const cls = i === state.pointer ? ' class="current"' : i > state.pointer ? ' class="future"' : '';
359	      return '<li' + cls + ' data-idx="' + i + '" title="回退到第 ' + i + ' 步：' + esc(r.label) + '（' + r.ts + '）' + (i > state.pointer ? ' · 之后操作将分叉' : '') + '">' +
360	        '<span class="seq">#' + pad2(r.seq) + '</span><span class="lbl">' + esc(r.label) + '</span><span class="ts">' + r.ts + '</span></li>';
361	    }).join('');
362	  }
363	
364	  function update() {
365	    const rows = sorted(matched());
366	    if (state.phase !== 'error') {
367	      state.phase = rows.length ? (state.selectedId ? 'selected' : 'ready') : 'empty';
368	    }
369	    app.setAttribute('data-app-state', state.phase);
370	    app.setAttribute('data-matched', String(rows.length));
371	    renderHeader(rows.length);
372	    renderChips();
373	    renderDimPanel();
374	    renderGrid(rows);
375	    renderInspector();
376	    renderTrail();
377	  }
378	
379	  /* ---------------- 事件（委托） ---------------- */
380	  function wire() {
381	    document.getElementById('dim-list').addEventListener('click', (e) => {
382	      const val = e.target.closest('.val');
383	      if (val) { actions.toggleFilter(val.getAttribute('data-dim'), val.getAttribute('data-val')); return; }
384	      const head = e.target.closest('.dim-head');
385	      if (head) actions.setFocus(head.parentElement.getAttribute('data-dim'));
386	    });
387	    document.getElementById('chips').addEventListener('click', (e) => {
388	      const x = e.target.closest('.x');
389	      if (!x) return;
390	      const kind = x.getAttribute('data-x');
391	      if (kind === 'filter') actions.toggleFilter(x.getAttribute('data-dim'), x.getAttribute('data-val'));
392	      else if (kind === 'focus') actions.setFocus(INITIAL_LENS.focus);
393	      else if (kind === 'clear-filters') actions.clearFilters();
394	      else if (kind === 'project-reset') actions.resetProjection();
395	      else if (kind === 'clear-sort') actions.setSort(state.lens.sort.key);
396	      else if (kind === 'clear-search') actions.setSearch('');
397	    });
398	    document.getElementById('proj-grid').addEventListener('change', (e) => {
399	      const k = e.target.getAttribute && e.target.getAttribute('data-proj');
400	      if (k) actions.toggleProjection(k);
401	    });
402	    document.getElementById('btn-proj-reset').addEventListener('click', () => actions.resetProjection());
403	    document.getElementById('grid-scroll').addEventListener('click', (e) => {
404	      if (e.target.id === 'btn-empty-clear') { actions.clearFilters(); return; }
405	      const th = e.target.closest('.th-sort');
406	      if (th) { actions.setSort(th.getAttribute('data-sort')); return; }
407	      const tr = e.target.closest('tr[data-id]');
408	      if (tr) { actions.select(tr.getAttribute('data-id')); }
409	    });
410	    document.getElementById('trail').addEventListener('click', (e) => {
411	      const li = e.target.closest('li[data-idx]');
412	      if (li) actions.jump(parseInt(li.getAttribute('data-idx'), 10));
413	    });
414	    document.getElementById('btn-undo').addEventListener('click', () => { actions.undo(); update(); });
415	    document.getElementById('btn-redo').addEventListener('click', () => { actions.redo(); update(); });
416	    document.getElementById('btn-reset').addEventListener('click', () => { actions.resetLens(); update(); });
417	
418	    let searchTimer = null;
419	    document.getElementById('search-input').addEventListener('input', function () {
420	      clearTimeout(searchTimer);
421	      const v = this.value;
422	      searchTimer = setTimeout(() => { actions.setSearch(v.trim()); update(); }, 300);
423	    });
424	
425	    document.addEventListener('keydown', (e) => {
426	      const inInput = e.target && (e.target.tagName === 'INPUT' || e.target.tagName === 'TEXTAREA');
427	      if ((e.ctrlKey || e.metaKey) && !inInput) {
428	        const k = e.key.toLowerCase();
429	        if (k === 'z' && !e.shiftKey) { e.preventDefault(); actions.undo(); update(); return; }
430	        if ((k === 'z' && e.shiftKey) || k === 'y') { e.preventDefault(); actions.redo(); update(); return; }
431	      }
432	      if (e.key === 'Escape' && !inInput) { state.selectedId = null; update(); }
433	      if (e.key === '/' && !inInput) { e.preventDefault(); document.getElementById('search-input').focus(); }
434	    });
435	
436	    // commit() 内部统一触发 update()；undo/redo/reset 等旁路操作在各自入口补一次刷新
437	  }
438	
439	  /* ---------------- 启动：完整性校验失败 → error 态；否则首屏即 ready ---------------- */
440	  function integrityCheck() {
441	    return !!(window.DATASET && Array.isArray(DATASET.records) && DATASET.records.length > 0 &&
442	      Array.isArray(DATASET.dims) && DATASET.dims.length >= 10 &&
443	      DATASET.records.every && typeof DATASET.records[0].id === 'string');
444	  }
445	
446	  function boot() {
447	    if (!integrityCheck()) {
448	      state.phase = 'error';
449	      app.setAttribute('data-app-state', 'error');
450	      app.innerHTML = '<div class="error-state" data-state="error" style="margin-top:40vh"><div class="big" style="font-size:16px;font-weight:700">数据集完整性校验失败</div><div style="margin-top:6px">内联数据缺失或格式不符 — 请检查 data.js 是否随页面正确加载。</div></div>';
451	      return;
452	    }
453	    buildSkeleton();
454	    wire();
455	    update(); // 首屏同步渲染完成 → ready（无加载态）
456	  }
457	
458	  boot();
459	})();
